import { lazy, Suspense, useCallback, useEffect, useId, useRef, useState, type FormEvent } from 'react';
import { ArrowLeft, Camera, ArrowDownLeft, CalendarDays, Check, ChevronLeft, ChevronRight, CircleDollarSign, History, Landmark, Pencil, Plus, Search, Settings, TrendingUp, LayoutGrid, List, Wallet, Trash2 } from 'lucide-react';
import ProjectionMonth, { MonthlyInvoices, type MonthlyInvoice } from './expense-month-details';
import ExpenseSplitFields from './expense-split-fields';
import PersonPortrait from './expense-person-portrait';
import AppearanceSettings from './appearance-settings';
import PageHeader from './page-header';
import ExpenseMobileSummary from './expense-control-mobile-summary';
import ExpenseSpendingHistory from './expense-spending-history';
import { FinanceDate } from './finance-date';
import OrderPopup from './order-popup';
import { expenseRequestId } from './expense-browser-crypto';
import { centsFromMoneyInput, maskMoneyInput, moneyInputFromCents } from './money-input';
import '../css/expense-control.css';
import '../css/expense-compact.css';
import CardArtworkPicker, { CardArtworkView, type CardArtwork } from './expense-card-artwork';

type Person = { id: number; name: string; user_id: number | null; default_percent: number };
type Institution = { restricted_type_id?: number | null; id: number; name: string; active: boolean; due_day: number; color: string; artwork_key?: string | null; image_url?: string | null };
type Kind = { id: number; name: string; active: boolean };
export type Configuration = { account_id: number; card_artworks: CardArtwork[]; people: Person[]; institutions: Institution[]; types: Kind[]; my_person_id: number | null; can_assign_users: boolean; accounts: { id: number; name: string }[] };
type Debt = { payers?: { paid_by: number | null; amount_cents: number }[]; payment_method?: string | null; id: number; name: string; institution_id: number; institution_name: string; type_id: number; type_name: string; recurrence: string; responsibility: string; percent_one: number; amount_cents: number; installment_count: number; first_number: number; start_on: string; due_day: number; notes: string | null; original_cents: number; paid_cents: number; discount_cents: number; remaining_cents: number; month_remaining_cents: number; cancelled_at: string | null; cancellation_reason: string | null; ended_on: string | null };
type Installment = { purchase_notes?: string | null; id: number; number: number; name: string; debt_id: number; month_on: string; due_on: string; amount_cents: number; share_one_cents: number; share_two_cents: number; remaining_one_cents: number; remaining_two_cents: number; remaining_cents: number; institution_name: string; paid_cents: number; discount_cents: number; status: string };
type Entry = { id: number; installment_id: number; name: string; institution_name: string; number: number; kind: string; paid_by: number | null; occurred_on: string; amount_cents: number; credit_one_cents: number; credit_two_cents: number; reversed_at: string | null; reversal_reason: string | null; notes: string | null; recorded_by: string | null };
type Detail = { debt: Debt; installments: Installment[]; entries: Entry[]; financial_locked: boolean };
type Pager<T> = { catalog_counts?: { institution_id: number; type_id: number; count: number }[]; data: T[]; current_page: number; last_page: number; total: number };
type ScopeSummary = { due_institutions?: { id: number; name: string; due_on: string; remaining_cents: number; count: number }[]; original_cents: number; paid_cents: number; remaining_cents: number; count: number; next_due: Installment[]; overdue: Installment[]; institutions: { id: number; name: string; remaining_cents: number; count: number }[] };
export type Summary = { monthly_invoices?: MonthlyInvoice[]; views?: Record<'one' | 'two' | 'shared', ScopeSummary>; partial_installments?: Installment[]; count: number; totals: Record<string, number>; institutions: { id: number; name: string; remaining_cents: number; original_cents: number; count: number }[]; next_due: Installment[]; overdue: Installment[]; personal_next_due: Installment[]; personal_overdue: Installment[] };
type Projection = { month: string; remaining_cents: number; one_cents: number; two_cents: number; shared_cents: number; count: number };
type Tab = 'summary' | 'debts' | 'institutions' | 'advances' | 'projection' | 'settled' | 'settings' | 'activity';
type Dialog = { kind: 'debt'; debt?: Debt } | { kind: 'catalog'; catalog: 'institutions' | 'types'; item?: Institution | Kind } | { kind: 'operation'; items: Installment[] } | { kind: 'installment'; item: Installment; responsibility: string } | { kind: 'reason'; action: 'cancel' | 'reverse'; id: number } | { kind: 'end'; id: number };
const tabs = [['summary', 'Resumo', Wallet], ['debts', 'Gastos', CircleDollarSign], ['institutions', 'Instituições', Landmark], ['advances', 'Pagamentos', ArrowDownLeft], ['projection', 'Projeção', TrendingUp], ['settled', 'Quitadas', Check], ['settings', 'Ajustes', Settings], ['activity', 'Histórico', History]] as const;
const emptyConfig: Configuration = { account_id: 0, card_artworks: [], people: [], institutions: [], types: [], my_person_id: null, can_assign_users: false, accounts: [] };
const money = (value = 0) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value) / 100);
const date = (value: string) => value ? value.slice(0, 10).split('-').reverse().join('/') : '—';
const monthLabel = (value: string) => new Date(value + '-01T12:00:00').toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
const currentMonth = () => new Date().toLocaleDateString('sv-SE').slice(0, 7);
const today = () => new Date().toLocaleDateString('sv-SE');
const kindLabel = (kind: string) => ({ payment: 'Pagamento', advance: 'Antecipação', discount: 'Abatimento' }[kind] || kind);
const statusLabel = (status: string) => ({ open: 'Em aberto', partial: 'Parcial', paid: 'Paga', cancelled: 'Cancelada' }[status] || status);
import { expenseControlApi as api } from './expense-control-api';
const PhotoImport = lazy(() => import('./expense-photo-import'));
const typesForInstitution = (config: Configuration, bank?: Institution) => config.types.filter(t => t.active && (!bank?.restricted_type_id || Number(bank.restricted_type_id) === t.id));

export default function ExpenseControlPage({ mobile = false }: { mobile?: boolean }) {
  const [projectionMonth, setProjectionMonth] = useState<string>();
  const [newDebtChoice, setNewDebtChoice] = useState(false);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [projectionSection, setProjectionSection] = useState<'future' | 'history'>('future');
  const [projectionView, setProjectionView] = useState<'cards' | 'list'>('list');
  const [scope, setScope] = useState<'one' | 'two' | 'shared'>('shared');
  const [view, setView] = useState<'cards' | 'list'>('cards');
  const preferenceAccount = useRef<number | null>(null);
  const changeView = (next: 'cards' | 'list') => { setView(next); if (config.account_id) { try { localStorage.setItem('arl-cg-view-user-' + config.account_id, next); } catch { /* Browser storage may be unavailable. */ } } };
  const [tab, setTab] = useState<Tab>('summary'), [month, setMonth] = useState(currentMonth), [config, setConfig] = useState(emptyConfig);
  const [summary, setSummary] = useState<Summary>(), [debts, setDebts] = useState<Pager<Debt>>(), [projection, setProjection] = useState<Projection[]>([]), [activity, setActivity] = useState<Pager<{ id: number; action: string; created_at: string; user_name: string; debt_name: string; reason: string }>>();
  const [detail, setDetail] = useState<Detail>(), [selected, setSelected] = useState<number[]>([]), [dialog, setDialog] = useState<Dialog>();
  const [q, setQ] = useState(''), [query, setQuery] = useState(''), [bank, setBank] = useState(''), [type, setType] = useState(''), [person, setPerson] = useState(''), [sort, setSort] = useState('newest'), [status, setStatus] = useState('active'), [page, setPage] = useState(1);
  const [error, setError] = useState(''), [notice, setNotice] = useState(''), [busy, setBusy] = useState(false), [loading, setLoading] = useState(true), [revision, setRevision] = useState(0);
  const [catalogRemoval, setCatalogRemoval] = useState<{ catalog: 'institutions' | 'types'; item: Institution | Kind }>();
  const [photoOpen, setPhotoOpen] = useState(false);
  const [institutionPayment, setInstitutionPayment] = useState(false);
  const [purchaseSettlement, setPurchaseSettlement] = useState(false);
  const detailRequest = useRef(0);
  useEffect(() => { const timer = setTimeout(() => { setQuery(q); setPage(1); }, 250); return () => clearTimeout(timer); }, [q]);
  useEffect(() => {
    const controller = new AbortController();
    setLoading(true); setError('');
    const params = new URLSearchParams({ month, page: String(page), q: query, sort, status: tab === 'settled' ? 'settled' : status });
    if (bank) params.set('institution', bank); if (type) params.set('type', type); if (person) params.set('person', person);
    const load = async () => {
      const [configuration, monthSummary] = await Promise.all([api<Configuration>('/configuration', 'GET', undefined, controller.signal), api<Summary>('/summary?month=' + month, 'GET', undefined, controller.signal)]);
      if (controller.signal.aborted) return;
      if (preferenceAccount.current !== configuration.account_id) {
        preferenceAccount.current = configuration.account_id;
        setScope(Number(configuration.my_person_id) === 1 ? 'one' : Number(configuration.my_person_id) === 2 ? 'two' : 'shared');
        try { setView(localStorage.getItem('arl-cg-view-user-' + configuration.account_id) === 'list' ? 'list' : 'cards'); } catch { setView('cards'); }
      }
      setConfig(configuration); setSummary(monthSummary);
      if (tab === 'debts' || tab === 'settled') setDebts(await api('/debts?' + params, 'GET', undefined, controller.signal));
      if (tab === 'projection') setProjection(await api('/projection?month=' + month, 'GET', undefined, controller.signal));
      if (tab === 'activity') setActivity(await api('/activity?page=' + page, 'GET', undefined, controller.signal));
    };
    void load().catch(e => { if (!controller.signal.aborted) setError(e.message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [tab, month, query, bank, type, person, sort, status, page, revision]);
  const showDetail = useCallback(async (id: number) => {
    const request = ++detailRequest.current;
    setError(''); setLoading(true);
    try { const result = await api<Detail>('/debts/' + id); if (request === detailRequest.current) { setDetail(result); setSelected([]); } }
    catch (e: any) { if (request === detailRequest.current) setError(e.message); }
    finally { if (request === detailRequest.current) setLoading(false); }
  }, []);
  const navigate = (next: Tab, preserveFilters = false) => { if (next === 'debts' && !preserveFilters) { setQ(''); setQuery(''); setBank(''); setType(''); setPerson(''); setStatus('active'); setSort('newest'); } ++detailRequest.current; setTab(next); if (next === 'projection') { setProjectionView('list'); setProjectionSection('future'); } setFiltersOpen(false); setDetail(undefined); setSelected([]); setPage(1); setNotice(''); };
  const openDialog = (next: Dialog) => { setError(''); setDialog(next); };
  const mutate = async (path: string, method: string, body: unknown) => {
    if (busy) return false;
    setBusy(true); setError('');
    try { await api(path, method, body); setDialog(undefined); setCatalogRemoval(undefined); setNotice('Alteração salva com sucesso.'); setRevision(n => n + 1); if (detail) await showDetail(detail.debt.id); return true; }
    catch (e: any) { setError(e.message); return false; }
    finally { setBusy(false); }
  };
  const name = (id: number) => config.people.find(p => p.id === id)?.name || 'Pessoa ' + id;
  const responsibility = (value: string) => value === 'shared' ? 'Casal' : name(value === 'one' ? 1 : 2);
  const total = summary?.totals || {};
  const scopeSummary = summary?.views?.[scope];
  const metricOriginal = scopeSummary?.original_cents || 0;
  const metricPaid = scopeSummary?.paid_cents || 0;
  const metricRemaining = scopeSummary?.remaining_cents || 0;
  const dueInstitutions = scopeSummary?.due_institutions || [];
  const nextPersonalDue = [...dueInstitutions].filter(i => i.due_on >= today()).sort((a, b) => a.due_on.localeCompare(b.due_on))[0];
  const goBank = (id: number) => { setBank(String(id)); setType(''); setQ(''); setStatus('active'); setQuery(''); navigate('debts', true); };
  const catalogCount = (institution: number, kind: number) => debts?.catalog_counts?.find(c => c.institution_id === institution && c.type_id === kind)?.count || 0;
  const countLabel = (kind: string, count: number) => /emprést|emprest/i.test(kind) ? (count === 1 ? 'empréstimo' : 'empréstimos') : /financia/i.test(kind) ? (count === 1 ? 'financiamento' : 'financiamentos') : /fix|casa/i.test(kind) ? (count === 1 ? 'despesa fixa' : 'despesas fixas') : (count === 1 ? 'compra' : 'compras');
  const viewButtons = <div className="cg-view-toggle" aria-label="Forma de exibição"><button disabled={!config.account_id || loading} aria-pressed={view === 'cards'} onClick={() => changeView('cards')}><LayoutGrid /> Cards</button><button disabled={!config.account_id || loading} aria-pressed={view === 'list'} onClick={() => changeView('list')}><List /> Lista</button></div>;
  const debtView = mobile ? 'list' : view;
  const projectionButtons = <div className="cg-view-toggle" aria-label="Forma de exibição da projeção"><button aria-pressed={projectionView === 'cards'} onClick={() => setProjectionView('cards')}><LayoutGrid /> Cards</button><button aria-pressed={projectionView === 'list'} onClick={() => setProjectionView('list')}><List /> Lista</button></div>;
  const payerCards = (personal = false) => {
    const people = personal && config.my_person_id ? config.people.filter(p => p.id === config.my_person_id) : config.people;
    return <div className={'cg-person-grid' + (people.length === 1 ? ' cg-person-single' : '')}>{people.map(p => {
      const key = p.id === 1 ? 'one' : 'two'; const original = total[key + '_original_cents'] || 0, remaining = total[key + '_remaining_cents'] || 0;
      return <article className="cg-person-card" key={p.id}><header><span className="cg-avatar">{<PersonPortrait kind={p.id === 1 ? 'man' : 'woman'} />}</span><div><small>RESPONSÁVEL</small><h3>{p.name}</h3></div></header><dl><div><dt>Valor original</dt><dd>{money(original)}</dd></div><div><dt>Pago / abatido</dt><dd>{money(original - remaining)}</dd></div><div><dt>Falta pagar</dt><dd className="cg-positive">{money(remaining)}</dd></div></dl><button onClick={() => { setPerson(p.id === 1 ? 'one' : 'two'); setBank(''); navigate('debts', true); }}>Ver seus gastos <ChevronRight /></button><small className="cg-card-note">Totais incluem sua parte das despesas do casal.</small></article>;
    })}{!personal && <article className="cg-person-card cg-shared"><header><span className="cg-avatar"><PersonPortrait kind="couple" /></span><div><small>COMPARTILHADO</small><h3>Casal</h3></div></header><dl><div><dt>Despesas compartilhadas</dt><dd>{money(total.shared_original_cents)}</dd></div><div><dt>Pago / abatido</dt><dd>{money((total.shared_original_cents || 0) - (total.shared_remaining_cents || 0))}</dd></div><div><dt>Falta pagar</dt><dd className="cg-positive">{money(total.shared_remaining_cents)}</dd></div></dl><button onClick={() => { setPerson('shared'); setBank(''); navigate('debts', true); }}>Ver gastos do casal <ChevronRight /></button><small className="cg-card-note">Este valor já está distribuído entre os dois responsáveis.</small></article>}</div>;
  };
  return <section className={"cg-page" + (mobile ? " cg-mobile" : "") + (debtView === 'list' ? ' cg-list-view' : '')} data-arl-expense-control-react="1">
    {mobile ? <header className="cgm-header"><div><span className="cg-eyebrow">SUAS FINANÇAS</span><h1>Controle de Gasto</h1></div><div className="cgm-header-actions"><ExpenseMonthPicker month={month} onChange={value => { setMonth(value); setSelected([]); }} /><button className="cg-create-action" disabled={loading} onClick={() => setNewDebtChoice(true)}><Plus /> Nova dívida</button></div></header> : <PageHeader title="Controle de Gasto" eyebrow="ORGANIZAÇÃO FINANCEIRA" description="Seus compromissos, os gastos do casal e os próximos passos, em um só lugar." icon={CircleDollarSign} actions={<><ExpenseMonthPicker month={month} onChange={value => { setMonth(value); setSelected([]); }} /><button className="cg-create-action" disabled={loading} onClick={() => setPhotoOpen(true)}><Camera /> Cadastrar por foto</button><button className="cg-create-action" onClick={() => openDialog({ kind: 'debt' })}><Plus /> Nova dívida</button></>} />}
    <div className="cg-navigation"><div className="cg-tabs" role="tablist" aria-label="Seções do Controle de Gasto">{tabs.filter(([id]) => !mobile || id !== 'activity').map(([id, label, Icon]) => <button key={id} role="tab" aria-selected={tab === id} onClick={() => navigate(id)} className={tab === id ? 'active' : ''}><Icon /><span>{label}</span></button>)}</div></div>
    {error && !dialog && <p className="cg-alert" role="alert">{error}</p>}{notice && <p className="cg-notice" role="status"><Check /> {notice}</p>}{loading && <p className="cg-loading" role="status">Atualizando informações…</p>}
    {tab === 'summary' && !detail && mobile && <ExpenseMobileSummary key={config.account_id + "-" + config.my_person_id} summary={summary} config={config} month={month} portraits={[<PersonPortrait key="one" kind="man" />, <PersonPortrait key="two" kind="woman" />, <PersonPortrait key="shared" kind="couple" />]} onInstitution={(id, selectedScope) => { setPerson(selectedScope === 'all' ? '' : selectedScope); goBank(id); }} onDebt={id => { void showDetail(id); setTab('debts'); }} />}
    {tab === 'summary' && !detail && !mobile && <>
      <div className="cg-section-heading"><div><span className="cg-eyebrow">SEU MÊS</span><h2>Visão geral do casal</h2><p>{monthLabel(month)} · {scopeSummary?.count || 0} cobranças nesta visão</p></div></div>
      <div className="cg-summary-scope cg-summary-filter" aria-label="Filtrar indicadores do resumo">{(['one', 'two', 'shared'] as const).map(value => <button key={value} aria-pressed={scope === value} onClick={() => setScope(value)}><PersonPortrait kind={value === 'shared' ? 'couple' : value === 'one' ? 'man' : 'woman'} />{value === 'shared' ? 'Casal' : name(value === 'one' ? 1 : 2)}</button>)}</div>
      <div className="cg-metrics"><article className="cg-metric-featured"><Wallet /><small>FALTA PAGAR NO MÊS</small><strong>{money(metricRemaining)}</strong><span>Saldo após pagamentos e abatimentos</span></article><article><CircleDollarSign /><small>TOTAL DO MÊS</small><strong>{money(metricOriginal)}</strong><span>Valor original das parcelas</span></article><article><Check /><small>PAGO / ANTECIPADO</small><strong>{money(metricPaid)}</strong><span>Abatimentos: {money(metricOriginal - metricPaid - metricRemaining)}</span></article><article><CalendarDays /><small>PRÓXIMO VENCIMENTO</small><strong>{nextPersonalDue ? date(nextPersonalDue.due_on).slice(0, 5) : '—'}</strong><span>{nextPersonalDue?.name || 'Nenhum vencimento pendente'}</span></article></div>
      <section className="cg-panel"><div className="cg-section-heading"><div><span className="cg-eyebrow">DIVISÃO DO MÊS</span><h2>{name(1) + ', ' + name(2) + ' e Casal'}</h2></div></div>{payerCards()}</section>
      {!!summary?.partial_installments?.length && <section className="cg-panel cg-partial-summary"><div className="cg-section-heading"><div><span className="cg-eyebrow">PAGAMENTOS PARCIAIS DO MÊS</span><h2>O que já foi baixado e o que falta</h2><p>Pago/abatido inclui pagamentos e descontos; cada parte mantém seu próprio saldo.</p></div></div>{summary.partial_installments.map(i => <article key={i.id}><header><div><b>{i.name}</b><small>{i.institution_name} · parcela {i.number} · vence {date(i.due_on)}</small></div><button onClick={() => { void showDetail(i.debt_id); setTab('debts'); }}>Ver parcela <ChevronRight /></button></header><div className="cg-partial-totals"><span>Parcela original <b>{money(i.amount_cents)}</b></span><span>Pago/abatido <b>{money(i.amount_cents - i.remaining_cents)}</b></span><span>Falta pagar <b>{money(i.remaining_cents)}</b></span></div><div className="cg-payment-split">{[1, 2].filter(id => (id === 1 ? i.share_one_cents : i.share_two_cents) > 0).map(id => { const original = id === 1 ? i.share_one_cents : i.share_two_cents; const pending = id === 1 ? i.remaining_one_cents : i.remaining_two_cents; return <article key={id}><span>{name(id)}</span><small>Parte original: {money(original)} · pago/abatido: {money(original - pending)}</small><strong>{pending === 0 ? 'Parte quitada' : 'Falta ' + money(pending)}</strong></article>; })}</div></article>)}</section>}
      <MonthlyInvoices items={summary?.monthly_invoices} onOpen={item => { if (item.debt_id !== null) { void showDetail(item.debt_id); setTab('debts'); } else { setPerson(''); goBank(item.institution_id); } }} />
    </>}
    {(tab === 'debts' || tab === 'settled') && !detail && <>
      <div className="cg-section-heading"><div><span className="cg-eyebrow">{tab === 'settled' ? 'HISTÓRICO PRESERVADO' : 'GESTÃO DE COMPROMISSOS'}</span><h2>{tab === 'settled' ? 'Dívidas quitadas' : 'Gastos e parcelas'}</h2><p>{tab === 'settled' ? 'Compras encerradas continuam disponíveis para consulta.' : 'Escolha a instituição e o tipo para abrir as compras.'}</p></div></div>
      {mobile && tab !== 'debts' && <button className="cgm-filter-toggle" aria-expanded={filtersOpen} aria-controls="cg-debt-filters" onClick={() => setFiltersOpen(!filtersOpen)}><Search /> {filtersOpen ? 'Fechar filtros' : 'Pesquisar e filtrar'}{(q || bank || type || person || status !== 'active' || sort !== 'newest') && <span>Filtros ativos</span>}</button>}
      {(!mobile || tab !== 'debts') && <div id="cg-debt-filters" className="cg-filters" hidden={mobile && !filtersOpen}><label className="cg-search"><Search /><input placeholder="Pesquisar compra ou instituição" aria-label="Pesquisar compra ou instituição" value={q} onChange={e => setQ(e.target.value)} /></label><label>Responsável<select aria-label="Filtrar por responsável" value={person} onChange={e => { setPerson(e.target.value); setPage(1); }}><option value="">Todos</option><option value="one">{name(1)}</option><option value="two">{name(2)}</option><option value="shared">Casal</option></select></label><label>Instituição<select value={bank} onChange={e => { setBank(e.target.value); setType(''); setPage(1); }}><option value="">Todas</option>{config.institutions.map(i => <option value={i.id} key={i.id}>{i.name}</option>)}</select></label><label>Tipo<select value={type} onChange={e => { setType(e.target.value); setPage(1); }}><option value="">Todos</option>{config.types.map(i => <option value={i.id} key={i.id}>{i.name}</option>)}</select></label>{tab === 'debts' && <label>Situação<select value={status} onChange={e => { setStatus(e.target.value); setPage(1); }}><option value="active">Ativas</option><option value="cancelled">Canceladas</option></select></label>}<label>Ordenar<select value={sort} onChange={e => setSort(e.target.value)}><option value="newest">Mais recentes</option><option value="oldest">Mais antigas</option><option value="name">Nome</option><option value="value">Maior saldo</option></select></label><button onClick={() => { setQ(''); setBank(''); setType(''); setPerson(''); setSort('newest'); setStatus('active'); setPage(1); }}>Limpar</button></div>}
      {!mobile && tab === 'debts' && !bank && !query && status === 'active' && <div className="cg-view-bar">{viewButtons}</div>}
      {tab === 'debts' && !bank && !query && status === 'active' && debtView === 'list' ? <div className="cg-bank-list">{config.institutions.filter(i => i.active).map(i => <article className="cg-bank-list-row" key={i.id}><button className="cg-institution" style={{ '--cg-bank-color': i.color } as React.CSSProperties} onClick={() => goBank(i.id)}>{!mobile && <CardArtworkView card={i} artworks={config.card_artworks} />}<h3>{i.name}</h3><span>Vencimento · dia {i.due_day}</span><footer>Ver tipos e compras <ChevronRight /></footer></button>{!mobile && <div className="cg-type-grid">{typesForInstitution(config, i).map(t => <button key={t.id} className="cg-panel" onClick={() => { setBank(String(i.id)); setType(String(t.id)); setPage(1); }}><CircleDollarSign /><h3>{t.name}</h3><strong className="cg-type-count">{loading ? '…' : catalogCount(i.id, t.id)} <small>{countLabel(t.name, catalogCount(i.id, t.id))}</small></strong><span>Abrir compras <ChevronRight /></span></button>)}</div>}</article>)}{!config.institutions.some(i => i.active) && <Empty title="Nenhuma instituição cadastrada" text="Cadastre uma instituição para começar." />}</div> : tab === 'debts' && !bank && !query && status === 'active' ? <div className="cg-bank-grid">{config.institutions.filter(i => i.active).map(i => <button className="cg-institution" key={i.id} style={{ '--cg-bank-color': i.color } as React.CSSProperties} onClick={() => goBank(i.id)}><span className="cg-eyebrow">INSTITUIÇÃO</span><CardArtworkView card={i} artworks={config.card_artworks} /><h3>{i.name}</h3><span>Vencimento padrão · dia {i.due_day}</span><div className="cg-institution-counts"><small>{person === 'one' ? name(1) : person === 'two' ? name(2) : person === 'shared' ? 'Casal' : 'Todos os responsáveis'}</small>{typesForInstitution(config, i).map(t => <div key={t.id}><span>{t.name}</span><b>{loading ? '…' : catalogCount(i.id, t.id)}</b></div>)}</div><footer>Ver tipos e compras <ChevronRight /></footer></button>)}{!config.institutions.some(i => i.active) && <Empty title="Nenhuma instituição cadastrada" text="Adicione seu cartão, banco ou grupo de despesas." action={<button onClick={() => navigate('institutions')}>Ir para Instituições</button>} />}</div> : <>
        {bank && <div className="cg-breadcrumb">{tab === 'debts' && !mobile && <><button onClick={() => setInstitutionPayment(true)}><CircleDollarSign /> Pagar fatura do mês</button><button onClick={() => setPurchaseSettlement(true)}><Check /> Quitar compra</button></>}<button onClick={() => { setBank(''); setType(''); }}>{mobile ? 'Voltar às instituições' : 'Instituições'}</button><ChevronRight /><span>{config.institutions.find(i => String(i.id) === bank)?.name}</span>{type && <><ChevronRight />{mobile ? <button onClick={() => { setType(''); setPage(1); }}>Voltar aos tipos</button> : <span>{config.types.find(i => String(i.id) === type)?.name}</span>}</>}</div>}
        {bank && !type && !query && tab === 'debts' && status === 'active' ? <div className={"cg-type-grid" + (mobile ? ' cgm-type-list' : '')}>{typesForInstitution(config, config.institutions.find(i => String(i.id) === bank)).map(i => <button className="cg-panel" key={i.id} onClick={() => { setType(String(i.id)); setPage(1); }}><CircleDollarSign /><h3>{i.name}</h3><strong className="cg-type-count">{loading ? '…' : catalogCount(Number(bank), i.id)} <small>{countLabel(i.name, catalogCount(Number(bank), i.id))}</small></strong><span>Abrir compras <ChevronRight /></span></button>)}{!config.types.some(i => i.active) && <Empty title="Cadastre um tipo de dívida" text="Cartão de crédito, empréstimo, despesas de casa…" action={<button onClick={() => navigate('institutions')}>Cadastrar tipo</button>} />}</div> : <section className="cg-panel">{debts?.data.map(d => <button className={"cg-debt-row" + (tab === 'settled' ? ' cg-settled-row' : '')} key={d.id} onClick={() => void showDetail(d.id)}><span className="cg-bank-icon"><CircleDollarSign /></span><span><b>{tab === 'settled' ? d.institution_name : d.name}</b><small>{tab === 'settled' ? d.name : d.institution_name + ' · ' + d.type_name + ' · ' + responsibility(d.responsibility)}</small>{tab === 'settled' && <small className="cg-settled-payers">{d.payers?.length ? 'Pago por ' + d.payers.map(p => (p.paid_by == null ? 'Casal' : name(Number(p.paid_by))) + ' · ' + money(p.amount_cents)).join(' / ') : 'Quitada por abatimento'}</small>}<small hidden={tab === 'settled'}>{d.recurrence === 'monthly' ? 'Assinatura / fixo mensal' : d.recurrence === 'once' ? 'Pagamento único' : d.installment_count + ' parcelas'} · vence dia {d.due_day}</small>{d.notes && <small className="cg-purchase-note" title={d.notes}>{d.notes}</small>}</span><span className="cg-row-values">{tab === 'settled' ? <><small>Total pago</small><strong>{money(d.paid_cents)}</strong>{Number(d.discount_cents) > 0 && <small>Abatimento: {money(d.discount_cents)}</small>}</> : <><small>Saldo cadastrado</small><strong>{money(d.remaining_cents)}</strong><small>No mês: {money(d.month_remaining_cents)}</small></>}</span><ChevronRight /></button>)}{!loading && !debts?.data.length && <Empty title={tab === 'settled' ? 'Nenhuma dívida quitada' : 'Nenhum gasto encontrado'} text="Os registros aparecerão aqui conforme seus cadastros e filtros." />}<Pagination current={debts?.current_page || 1} last={debts?.last_page || 1} onChange={setPage} /></section>}
      </>}
      {mobile && bank && tab === 'debts' && <div className="cgm-institution-actions"><button onClick={() => setInstitutionPayment(true)}><CircleDollarSign /> Pagar fatura do mês</button><button onClick={() => setPurchaseSettlement(true)}><Check /> Quitar compra</button></div>}
    </>}
    {detail && (tab === 'debts' || tab === 'settled') && <>
      <button className="cg-back" onClick={() => { ++detailRequest.current; setDetail(undefined); setSelected([]); }}><ArrowLeft /> Voltar aos gastos</button>
      <section className="cg-panel cg-debt-header"><div className="cg-debt-heading"><div className="cg-debt-identity"><span className="cg-eyebrow">{detail.debt.institution_name} · {detail.debt.type_name}</span><h2>{detail.debt.name}</h2><p>{responsibility(detail.debt.responsibility)} · {detail.debt.recurrence === 'monthly' ? 'Mensal recorrente' : detail.debt.recurrence === 'once' ? 'Pagamento único' : detail.debt.installment_count + ' parcelas'} · vence dia {detail.debt.due_day}</p></div>{detail.debt.cancelled_at ? <p className="cg-alert">Cancelada: {detail.debt.cancellation_reason}</p> : <div className="cg-actions"><button onClick={() => openDialog({ kind: 'debt', debt: detail.debt })}><Pencil /> Editar identificação</button>{detail.debt.recurrence === 'monthly' && !detail.debt.ended_on && <button onClick={() => openDialog({ kind: 'end', id: detail.debt.id })}>Encerrar recorrência</button>}<button className="cg-danger" onClick={() => openDialog({ kind: 'reason', action: 'cancel', id: detail.debt.id })}>Excluir dívida</button></div>}</div><div className="cg-detail-totals"><span>Valor original cadastrado<strong>{money(detail.installments.reduce((sum, i) => sum + Number(i.amount_cents), 0))}</strong></span><span>Pago / abatido<strong>{money(detail.installments.reduce((sum, i) => sum + Number(i.amount_cents) - i.remaining_cents, 0))}</strong></span><span>Saldo restante<strong>{money(detail.installments.reduce((sum, i) => sum + i.remaining_cents, 0))}</strong></span></div>{detail.debt.notes && <p className="cg-debt-note">{detail.debt.notes}</p>}</section>
      <section className="cg-panel"><div className="cg-section-heading"><div><span className="cg-eyebrow">PARCELAS</span><h2>Valores e responsabilidades</h2></div><button disabled={!!detail.debt.cancelled_at} onClick={() => setSelected(detail.installments.filter(i => i.remaining_cents > 0).map(i => i.id))}>Selecionar pendentes</button></div>{selected.length > 0 && <div className="cg-selection"><strong>{selected.length} parcelas selecionadas</strong><span>{money(detail.installments.filter(i => selected.includes(i.id)).reduce((sum, i) => sum + i.remaining_cents, 0))}</span><button className="cg-primary" onClick={() => openDialog({ kind: 'operation', items: detail.installments.filter(i => selected.includes(i.id)) })}>Registrar pagamento</button><button onClick={() => setSelected([])}>Limpar seleção</button></div>}<div className="cg-table-wrap"><table><thead><tr><th>Selecionar</th><th>Parcela / vencimento</th><th>Original</th><th>{name(1)} · falta</th><th>{name(2)} · falta</th><th>Situação</th><th>Ações</th></tr></thead><tbody>{detail.installments.map(i => <tr key={i.id}><td><input type="checkbox" aria-label={'Selecionar parcela ' + i.number} checked={selected.includes(i.id)} disabled={i.remaining_cents <= 0 || !!detail.debt.cancelled_at} onChange={e => setSelected(ids => e.target.checked ? [...ids, i.id] : ids.filter(id => id !== i.id))} /></td><td><b>{detail.debt.recurrence === 'monthly' ? 'Mensal · ' + i.number : i.number + '/' + detail.debt.installment_count}</b><small>{date(i.due_on)}</small>{i.purchase_notes && <small className="cg-purchase-note" title={i.purchase_notes}>{i.purchase_notes}</small>}</td><td data-label="Original">{money(i.amount_cents)}</td><td data-label={name(1) + " · falta"}>{money(i.remaining_one_cents)}</td><td data-label={name(2) + " · falta"}>{money(i.remaining_two_cents)}</td><td><span className={'cg-status cg-status-' + i.status}>{statusLabel(i.status)}</span></td><td><div className="cg-actions">{i.remaining_cents > 0 && !detail.debt.cancelled_at && <button onClick={() => openDialog({ kind: 'operation', items: [i] })}>Pagar</button>}{!detail.entries.some(e => e.installment_id === i.id) && !detail.debt.cancelled_at && <button aria-label={'Editar parcela ' + i.number} onClick={() => openDialog({ kind: 'installment', item: i, responsibility: detail.debt.responsibility })}><Pencil /></button>}</div></td></tr>)}</tbody></table></div>{detail.debt.recurrence === 'monthly' && <p className="cg-muted">Os meses da despesa recorrente são gerados conforme consulta ao resumo e à projeção.</p>}</section>
      <section className="cg-panel"><div className="cg-section-heading"><div><span className="cg-eyebrow">HISTÓRICO FINANCEIRO</span><h2>Pagamentos, antecipações e abatimentos</h2></div></div>{detail.entries.map(e => <EntryRow key={e.id} entry={e} name={name} onReverse={() => openDialog({ kind: 'reason', action: 'reverse', id: e.id })} />)}{!detail.entries.length && <Empty title="Nenhum lançamento" text="Cada pagamento ficará registrado aqui, com data e responsável." />}</section>
    </>}
    {tab === 'institutions' && <>
      <div className="cg-section-heading"><div><span className="cg-eyebrow">CADASTROS FINANCEIROS</span><h2>Instituições e tipos de dívida</h2><p>Organize seus cartões, bancos e despesas sem misturar com as contas da empresa.</p></div><button className="cg-primary" onClick={() => openDialog({ kind: 'catalog', catalog: 'institutions' })}><Plus /> Cadastrar instituição</button></div><div className="cg-bank-grid">{config.institutions.map(i => <article className={'cg-institution' + (!i.active ? ' inactive' : '')} style={{ '--cg-bank-color': i.color } as React.CSSProperties} key={i.id}><span className="cg-eyebrow">{i.active ? 'INSTITUIÇÃO ATIVA' : 'INATIVA'}</span><CardArtworkView card={i} artworks={config.card_artworks} /><h3>{i.name}</h3><span>Vencimento padrão · dia {i.due_day}</span><footer><button aria-label={'Ver gastos de ' + i.name} onClick={() => goBank(i.id)}>{mobile ? <CircleDollarSign /> : 'Ver gastos'}</button><button aria-label={'Editar instituição ' + i.name} onClick={() => openDialog({ kind: 'catalog', catalog: 'institutions', item: i })}><Pencil /></button><button aria-label={'Excluir instituição ' + i.name} onClick={() => { setError(''); setCatalogRemoval({ catalog: 'institutions', item: i }); }}><Trash2 /></button></footer></article>)}</div><section className="cg-panel"><div className="cg-section-heading"><div><span className="cg-eyebrow">CLASSIFICAÇÃO</span><h2>Tipos de dívida</h2></div><button onClick={() => openDialog({ kind: 'catalog', catalog: 'types' })}><Plus /> Cadastrar tipo</button></div><div className="cg-type-chips">{config.types.map(t => <div className="cg-type-actions" key={t.id}><button onClick={() => openDialog({ kind: 'catalog', catalog: 'types', item: t })}>{t.name}{!t.active && ' · inativo'} <Pencil /></button><button aria-label={'Excluir tipo ' + t.name} onClick={() => { setError(''); setCatalogRemoval({ catalog: 'types', item: t }); }}><Trash2 /></button></div>)}</div>{!config.types.length && <p className="cg-muted">Exemplos: cartão de crédito, empréstimo, financiamento e despesas de casa.</p>}</section>
    </>}
    {tab === 'projection' && <><div className="cg-projection-sections" aria-label="Seções da projeção"><button aria-pressed={projectionSection === 'future'} onClick={() => setProjectionSection('future')}>Projeção futura</button><button aria-pressed={projectionSection === 'history'} onClick={() => setProjectionSection('history')}>Histórico de gastos</button></div>{projectionSection === 'history' ? <ExpenseSpendingHistory month={month} people={config.people} /> : <><div className="cg-section-heading"><div><span className="cg-eyebrow">PRÓXIMOS 12 MESES</span><h2>Compromissos futuros</h2><p>Saldo a pagar, considerando pagamentos e abatimentos já registrados.</p></div></div>{projectionButtons}<div className={"cg-projection-grid" + (projectionView === 'list' ? ' cg-projection-list' : '')}>{projection.map(p => <article className="cg-panel" key={p.month}><span className="cg-eyebrow">{monthLabel(p.month)}</span><strong>{money(p.remaining_cents)}</strong><p>{p.count} cobranças pendentes</p><dl><div><dt><PersonPortrait kind="man" />{name(1)}</dt><dd>{money(p.one_cents)}</dd></div><div><dt><PersonPortrait kind="woman" />{name(2)}</dt><dd>{money(p.two_cents)}</dd></div><div><dt><PersonPortrait kind="couple" />Despesas compartilhadas</dt><dd>{money(p.shared_cents)}</dd></div></dl><button onClick={() => setProjectionMonth(p.month)}>Ver mês <ChevronRight /></button></article>)}</div></>}</>}    {tab === 'advances' && <PaymentInstitutions key={month + '-' + revision} month={month} config={config} name={name} mobile={mobile} onReverse={id => openDialog({ kind: 'reason', action: 'reverse', id })} /> }
    {tab === 'settings' && <><section className="cg-panel cg-appearance-panel"><AppearanceSettings /></section><PeopleSettings key={revision + '-' + config.people.map(p => p.name + p.user_id).join(',')} config={config} busy={busy} onSave={data => mutate('/people', 'PUT', data)} /></>}
    {tab === 'activity' && <section className="cg-panel"><div className="cg-section-heading"><div><span className="cg-eyebrow">EXCLUSÕES DO MÓDULO</span><h2>Dívidas excluídas</h2></div></div>{activity?.data.map(a => <div className="cg-log" key={a.id}><History /><span><b>{a.debt_name}</b><p>Motivo: {a.reason}</p><small>{a.user_name || 'Conta removida'} · <FinanceDate value={a.created_at} /></small></span></div>)}{!loading && !activity?.data.length && <Empty title="Nenhuma atividade registrada" text="Somente dívidas excluídas aparecem aqui, com o motivo e quem excluiu." />}<Pagination current={activity?.current_page || 1} last={activity?.last_page || 1} onChange={setPage} /></section>}
    {projectionMonth && <ProjectionMonth month={projectionMonth} names={[name(1), name(2)]} onClose={() => setProjectionMonth(undefined)} />}
    {newDebtChoice && <OrderPopup title="Nova dívida" eyebrow="CONTROLE DE GASTO" description="Escolha como deseja cadastrar." icon={Plus} variant="budget" theme="expense" closeLabel="Fechar opções de cadastro" onClose={() => setNewDebtChoice(false)}><div className="cg-dialog-body cgm-debt-choice"><button onClick={() => { setNewDebtChoice(false); openDialog({ kind: 'debt' }); }}><Pencil /><span><b>Cadastro manual</b><small>Informe a compra, parcelas e responsável.</small></span><ChevronRight /></button><button disabled={loading} onClick={() => { setNewDebtChoice(false); setPhotoOpen(true); }}><Camera /><span><b>Cadastrar por foto</b><small>Leia a fatura com IA e confira as compras.</small></span><ChevronRight /></button></div></OrderPopup>}
    {photoOpen && <Suspense fallback={<p role="status">Preparando cadastro por foto…</p>}><PhotoImport config={config} month={month} institution={bank} onClose={() => setPhotoOpen(false)} onSaved={(count, id) => { setPhotoOpen(false); goBank(id); setNotice(count + " compras cadastradas por foto."); setRevision(n => n + 1); }} /></Suspense>}
    {purchaseSettlement && <PurchaseSettlement bank={Number(bank)} busy={busy} saveError={error} onClose={() => { if (!busy) setPurchaseSettlement(false); }} onSave={async (id, data) => { const ok = await mutate('/debts/' + id + '/settlement', 'POST', data); if (ok) setPurchaseSettlement(false); return ok; }} />}
    {institutionPayment && <InstitutionPayment bank={Number(bank)} month={month} config={config} initialTarget={person === 'two' ? 'two' : 'one'} busy={busy} saveError={error} onClose={() => { if (!busy) setInstitutionPayment(false); }} onSave={async data => { const ok = await mutate('/institution-payments', 'POST', data); if (ok) setInstitutionPayment(false); return ok; }} />}
    {catalogRemoval && <OrderPopup theme="expense" variant="editor" icon={Trash2} description="Exclua somente cadastros sem saldo pendente." title="Excluir cadastro" eyebrow="CONTROLE DE GASTO" onClose={() => { if (!busy) { setCatalogRemoval(undefined); setError(''); } }}><div className="cg-dialog cg-form cg-catalog-delete"><div className="cg-dialog-body"><h3>{catalogRemoval.item.name}</h3><p>Confirma a exclusão deste cadastro? Só será permitido se não houver parcelas em aberto, inclusive futuras, nem despesas recorrentes em andamento. Compras e pagamentos anteriores permanecerão no histórico.</p>{error && <p className="cg-alert" role="alert">{error}</p>}</div><footer className="cg-dialog-footer"><button disabled={busy} onClick={() => { setCatalogRemoval(undefined); setError(''); }}>Cancelar</button><button disabled={busy} onClick={() => void mutate('/catalogs/' + catalogRemoval.catalog + '/' + catalogRemoval.item.id, 'DELETE', { confirmed: true })}><Trash2 /> Confirmar exclusão</button></footer></div></OrderPopup>}
    {dialog && <ExpenseDialog key={dialog.kind + ('id' in dialog ? dialog.id : '')} dialog={dialog} config={config} month={month} busy={busy} error={error} onClose={() => { if (!busy) { setDialog(undefined); setError(''); } }} onSave={mutate} />}
  </section>;
}

function Empty({ title, text, action }: { title: string; text: string; action?: React.ReactNode }) { return <div className="cg-empty"><CircleDollarSign /><h3>{title}</h3><p>{text}</p>{action}</div>; }
function Pagination({ current, last, onChange }: { current: number; last: number; onChange: (page: number) => void }) { return last > 1 ? <div className="cg-pagination"><button disabled={current === 1} onClick={() => onChange(current - 1)}><ChevronLeft /> Anterior</button><span>Página {current} de {last}</span><button disabled={current === last} onClick={() => onChange(current + 1)}>Próxima <ChevronRight /></button></div> : null; }
function EntryRow({ entry: e, name, onReverse }: { entry: Entry; name: (id: number) => string; onReverse: () => void }) { return <article className={'cg-entry' + (e.reversed_at ? ' reversed' : '')}><span className="cg-bank-icon"><ArrowDownLeft /></span><div><b>{e.name || 'Parcela ' + e.number}</b><small>{kindLabel(e.kind)} · parcela {e.number} · {date(e.occurred_on)} · {e.paid_by ? 'Pago por ' + name(e.paid_by) : e.kind === 'discount' ? 'Redução do saldo' : 'Pago pelo casal'}</small><small>{name(1)}: {money(e.credit_one_cents)} · {name(2)}: {money(e.credit_two_cents)}{e.institution_name && ' · ' + e.institution_name}</small>{e.notes && <small>{e.notes}</small>}{e.reversed_at && <small>Desfeito: {e.reversal_reason}</small>}</div><strong>{money(e.amount_cents)}</strong>{!e.reversed_at && <button onClick={onReverse}>Desfazer</button>}</article>; }

function PeopleSettings({ config, busy, onSave }: { config: Configuration; busy: boolean; onSave: (data: unknown) => Promise<boolean> }) {
  const [people, setPeople] = useState(config.people);
  const update = (index: number, data: Partial<Person>) => setPeople(rows => rows.map((p, n) => n === index ? { ...p, ...data } : p));
  return <form className="cg-panel cg-form" onSubmit={e => { e.preventDefault(); void onSave({ people }); }}><div className="cg-section-heading"><div><span className="cg-eyebrow">RESPONSÁVEIS E DIVISÃO</span><h2>Quem participa do controle</h2><p>O padrão vale para novos gastos compartilhados. Parcelas já cadastradas mantêm sua divisão.</p></div></div><div className="cg-two-columns">{people.map((p, index) => <fieldset key={p.id}><legend>Responsável {p.id}</legend><label>Nome<input required maxLength={80} value={p.name} onChange={e => update(index, { name: e.target.value })} /></label><label>Divisão padrão (%)<input type="number" min="0" max="100" required value={p.default_percent} onChange={e => { const n = Number(e.target.value); update(index, { default_percent: n }); setPeople(rows => rows.map((p, i) => i !== index ? { ...p, default_percent: 100 - n } : p)); }} /></label>{config.can_assign_users && <label>Conta vinculada ao resumo pessoal<select value={p.user_id || ''} onChange={e => update(index, { user_id: e.target.value ? Number(e.target.value) : null })}><option value="">Sem vínculo</option>{config.accounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></label>}</fieldset>)}</div><p className="cg-muted">Contas de acesso são criadas pelo Master em Usuários. O perfil Controle de Gasto acessa somente este módulo.</p><div className="cg-actions"><button className="cg-primary" disabled={busy || people.length !== 2}>{busy ? 'Salvando…' : 'Salvar responsáveis'}</button></div></form>;
}

function ExpenseDialog({ dialog, config, month, busy, error, onClose, onSave }: { dialog: Dialog; config: Configuration; month: string; busy: boolean; error: string; onClose: () => void; onSave: (path: string, method: string, data: unknown) => Promise<boolean> }) {
  const requestKey = useRef(expenseRequestId());
  const [cardFile, setCardFile] = useState<File | null>(null);
  const [pendingCrop, setPendingCrop] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const needsConfirmation = dialog.kind === 'installment' || dialog.kind === 'reason' || dialog.kind === 'end' || (dialog.kind === 'debt' && !!dialog.debt) || (dialog.kind === 'catalog' && !!dialog.item);
  const [form, setForm] = useState<Record<string, any>>(() => {
    if (dialog.kind === 'debt') return dialog.debt ? { name: dialog.debt.name, notes: dialog.debt.notes || '', payment_method: dialog.debt.payment_method || '', institution_id: String(dialog.debt.institution_id), start_month: dialog.debt.start_on.slice(0, 7), due_day: dialog.debt.due_day } : { split_mode: 'percent', share_one_value: '', name: '', payment_method: '', institution_id: '', type_id: '', recurrence: 'installments', responsibility: '', percent_one: config.people[0]?.default_percent ?? 50, value: '', installment_count: 2, first_number: 1, start_month: month, due_day: 10, notes: '' };
    if (dialog.kind === 'catalog') return dialog.item ? { ...dialog.item } : { name: '', active: true, household: false, due_day: 10, color: '#c9002c' };
    if (dialog.kind === 'operation') return { kind: 'payment', target: 'both', paid_by: config.my_person_id || '', occurred_on: today(), value: '', partial: false, notes: '' };
    if (dialog.kind === 'installment') return { split_mode: 'amount', share_one_value: moneyInputFromCents(dialog.item.share_one_cents), value: moneyInputFromCents(dialog.item.amount_cents), percent_one: Math.round(Number(dialog.item.share_one_cents) * 100 / Number(dialog.item.amount_cents)), due_on: dialog.item.due_on };
    if (dialog.kind === 'end') return { end_month: month };
    return { reason: '' };
  });
  const change = (key: string, value: any) => setForm(f => ({ ...f, [key]: value }));
  const title = dialog.kind === 'debt' ? dialog.debt ? 'Editar identificação da dívida' : 'Cadastrar nova dívida' : dialog.kind === 'catalog' ? (dialog.item ? 'Editar ' : 'Cadastrar ') + (dialog.catalog === 'institutions' ? 'instituição' : 'tipo de dívida') : dialog.kind === 'operation' ? 'Registrar pagamento ou abatimento' : dialog.kind === 'installment' ? 'Editar parcela' : dialog.kind === 'end' ? 'Encerrar despesa recorrente' : dialog.action === 'reverse' ? 'Desfazer lançamento' : 'Excluir dívida';
  const name = (id: number) => config.people.find(p => p.id === id)?.name || 'Pessoa ' + id;
  const remaining = dialog.kind === 'operation' ? dialog.items.reduce((sum, i) => sum + (form.target === 'one' ? i.remaining_one_cents : form.target === 'two' ? i.remaining_two_cents : i.remaining_cents), 0) : 0;
  const sharedPayment = dialog.kind === 'operation' && dialog.items.every(i => i.share_one_cents > 0 && i.share_two_cents > 0);
  const paymentMode = form.partial ? 'partial' : form.target;
  const paymentPreview = dialog.kind === 'operation' ? dialog.items.reduce((result, i) => {
    const one = form.target === 'two' ? 0 : i.remaining_one_cents;
    const two = form.target === 'one' ? 0 : i.remaining_two_cents;
    const amount = Math.min(one + two, Math.max(0, form.partial ? centsFromMoneyInput(form.value) : one + two));
    const creditOne = one === 0 ? 0 : two === 0 ? amount : Math.min(one, Math.floor((amount * one + Math.floor((one + two) / 2)) / (one + two)));
    return { one: result.one + i.remaining_one_cents - creditOne, two: result.two + i.remaining_two_cents - (amount - creditOne), amount: result.amount + amount };
  }, { one: 0, two: 0, amount: 0 }) : { one: 0, two: 0, amount: 0 };
  const choosePayment = (mode: string) => setForm(f => ({ ...f, partial: mode === 'partial', target: mode === 'partial' ? 'both' : mode, value: '', paid_by: mode === 'one' ? 1 : mode === 'two' ? 2 : f.paid_by }));
  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (dialog.kind === 'debt') {
      if (dialog.debt) void onSave('/debts/' + dialog.debt.id, 'PUT', form);
      else { const { value, share_one_value, split_mode, ...data } = form; void onSave('/debts', 'POST', { ...data, split_mode: form.recurrence === 'monthly' ? 'percent' : split_mode, share_one_cents: centsFromMoneyInput(share_one_value), share_two_cents: form.responsibility === 'shared' && split_mode === 'amount' && form.recurrence !== 'monthly' ? centsFromMoneyInput(value) - centsFromMoneyInput(share_one_value) : null, institution_id: Number(form.institution_id), type_id: Number(form.type_id), amount_cents: centsFromMoneyInput(value), request_key: requestKey.current }); }
    } else if (dialog.kind === 'catalog') {
      const path = '/catalogs/' + dialog.catalog + (dialog.item ? '/' + dialog.item.id : '');
      if (dialog.catalog === 'institutions') {
        if (pendingCrop) return;
        const data = new FormData();
        data.append('household', form.household || form.restricted_type_id ? '1' : '0');
        for (const key of ['name', 'due_day', 'color', 'artwork_key']) data.append(key, String(form[key] ?? ''));
        data.append('active', form.active ? '1' : '0');
        data.append('remove_image', form.remove_image ? '1' : '0');
        if (dialog.item) data.append('_method', 'PUT');
        if (cardFile) data.append('image', cardFile);
        void onSave(path, 'POST', data);
      } else void onSave(path, dialog.item ? 'PUT' : 'POST', form);
    }
    else if (dialog.kind === 'operation') void onSave('/operations', 'POST', { request_key: requestKey.current, installment_ids: dialog.items.map(i => i.id), kind: form.kind, target: form.target, paid_by: form.kind === 'discount' ? null : Number(form.paid_by), occurred_on: form.occurred_on, notes: form.notes, amount_cents: form.partial ? centsFromMoneyInput(form.value) : null });
    else if (dialog.kind === 'installment') void onSave('/installments/' + dialog.item.id, 'PUT', { split_mode: form.split_mode, share_one_cents: centsFromMoneyInput(form.share_one_value), share_two_cents: dialog.responsibility === 'shared' && form.split_mode === 'amount' ? centsFromMoneyInput(form.value) - centsFromMoneyInput(form.share_one_value) : null, amount_cents: centsFromMoneyInput(form.value), percent_one: form.percent_one, due_on: form.due_on });
    else if (dialog.kind === 'end') void onSave('/debts/' + dialog.id + '/end-recurring', 'POST', form);
    else void onSave(dialog.action === 'cancel' ? '/debts/' + dialog.id + '/cancel' : '/entries/' + dialog.id + '/reverse', 'POST', form);
  };
  const amountField = (label: string) => <label>{label}<input aria-label={label} inputMode="numeric" required value={form.value} placeholder="0,00" onChange={e => change('value', maskMoneyInput(e.target.value))} /></label>;
  return <OrderPopup theme="expense" title={title} eyebrow="CONTROLE DE GASTO" description="Informações organizadas, valores exatos e histórico preservado." icon={dialog.kind === 'catalog' ? Landmark : CircleDollarSign} variant="budget" closeLabel="Fechar formulário de gasto" onClose={onClose}><form className={"cg-dialog cg-form" + (dialog.kind === 'debt' && !dialog.debt ? ' cg-debt-entry' : '')} onSubmit={e => { if (needsConfirmation && !confirming) { e.preventDefault(); setConfirming(true); } else submit(e); }}><div className="cg-dialog-body">{confirming && <div className="cg-panel" role="status"><h3>{dialog.kind === 'reason' && dialog.action === 'cancel' ? 'Confirma excluir esta dívida?' : 'Confirma esta alteração?'}</h3><p>{dialog.kind === 'reason' && dialog.action === 'cancel' ? 'A dívida sairá dos gastos. O cadastro e os pagamentos permanecerão no histórico de canceladas.' : 'Confira os dados antes de confirmar. A alteração ficará registrada no histórico.'}</p><button type="button" onClick={() => setConfirming(false)}>Voltar à edição</button></div>}<fieldset disabled={busy || confirming}>
    {error && <p role="alert" className="cg-alert">{error}</p>}
    {dialog.kind === 'debt' && <><label>Nome da dívida ou compra<input required maxLength={200} value={form.name} onChange={e => change('name', e.target.value)} /></label>{!dialog.debt && <><div className="cg-two-columns"><label>Instituição<select required value={form.institution_id} onChange={e => { const bank = config.institutions.find(i => String(i.id) === e.target.value); setForm(f => ({ ...f, institution_id: e.target.value, type_id: bank?.restricted_type_id ? String(bank.restricted_type_id) : '', recurrence: bank?.restricted_type_id ? 'monthly' : f.recurrence, due_day: bank?.due_day || 10 })); }}><option value="">Selecione a instituição</option>{config.institutions.filter(i => i.active).map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</select></label><label>Tipo de dívida<select required value={form.type_id} onChange={e => change('type_id', e.target.value)}><option value="">Selecione o tipo</option>{typesForInstitution(config, config.institutions.find(i => String(i.id) === String(form.institution_id))).map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</select></label></div>{(!config.institutions.some(i => i.active) || !config.types.some(i => i.active)) && <p className="cg-muted">Antes de cadastrar a dívida, adicione a instituição e o tipo na seção Instituições.</p>}<div className="cg-two-columns"><label>Como a cobrança se repete?<select value={form.recurrence} onChange={e => setForm(f => ({ ...f, recurrence: e.target.value, installment_count: e.target.value === 'installments' ? 2 : 1, first_number: 1 }))}><option value="installments">Parcelado</option><option value="monthly">Fixo / assinatura mensal (até cancelar)</option><option value="once">Só uma vez</option></select></label><label>Quem paga esta fatura?<select required value={form.responsibility} onChange={e => change('responsibility', e.target.value)}><option value="">Selecione quem paga</option><option value="one">{name(1)}</option><option value="two">{name(2)}</option><option value="shared">Casal</option></select></label></div><div className="cg-two-columns">{amountField(form.recurrence === 'installments' ? 'Valor de cada parcela (R$)' : 'Valor da cobrança (R$)')}<label>Primeira cobrança em<input required type="month" min="2000-01" max="2099-12" value={form.start_month} onChange={e => change('start_month', e.target.value)} /></label></div><div className="cg-two-columns">{form.recurrence === 'installments' && <><label>Quantidade total de parcelas<input required type="number" min="1" max="360" value={form.installment_count} onChange={e => change('installment_count', Number(e.target.value))} /></label><label>Número da primeira parcela cadastrada<input required type="number" min="1" max={form.installment_count} value={form.first_number} onChange={e => change('first_number', Number(e.target.value))} /></label></>}<label>Dia de vencimento<input required type="number" min="1" max="31" value={form.due_day} onChange={e => change('due_day', Number(e.target.value))} /></label>{form.responsibility === 'shared' && <ExpenseSplitFields amount={centsFromMoneyInput(form.value)} mode={form.split_mode} percent={Number(form.percent_one)} one={form.share_one_value || ''} names={[name(1), name(2)]} allowAmounts={form.recurrence !== 'monthly'} onChange={data => setForm(f => ({ ...f, ...data }))} />}</div></>}{dialog.debt && <><div className="cg-two-columns"><label>Cartão ou instituição<select required value={form.institution_id} onChange={e => change('institution_id', e.target.value)}>{config.institutions.filter(i => i.active || i.id === dialog.debt?.institution_id).map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</select></label><label>Primeiro vencimento em<input required type="month" min="2000-01" max="2099-12" value={form.start_month} onChange={e => change('start_month', e.target.value)} /></label><label>Dia de vencimento<input required type="number" min="1" max="31" value={form.due_day} onChange={e => change('due_day', Number(e.target.value))} /></label></div><p className="cg-muted">Mudar o primeiro vencimento reorganiza todos os meses, mantendo os valores e a divisão. Cartão e vencimentos em lote só podem mudar antes de qualquer pagamento, abatimento ou estorno.</p></>}<label>Forma de pagamento prevista (opcional)<select value={form.payment_method || ''} onChange={e => change('payment_method', e.target.value)}><option value="">Não informada</option><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="boleto">Boleto</option><option value="card">Cartão</option><option value="transfer">Transferência</option><option value="other">Outra</option></select></label><label>Observação opcional<textarea rows={3} maxLength={2000} value={form.notes} onChange={e => change('notes', e.target.value)} /></label>{dialog.debt && <p className="cg-muted">Valores e divisão são ajustados por parcela, preservando o histórico de pagamentos.</p>}</>}
    {dialog.kind === 'catalog' && <><label>Nome<input required maxLength={80} value={form.name} onChange={e => change('name', e.target.value)} /></label>{dialog.catalog === 'institutions' && <div className="cg-two-columns"><label>Dia padrão de vencimento<input required type="number" min="1" max="31" value={form.due_day} onChange={e => change('due_day', Number(e.target.value))} /></label></div>}{dialog.catalog === 'institutions' && <><p className="cg-muted">Escolha o modelo Fixos de Casa para cadastrar um grupo exclusivo de contas de luz, água, internet e outras despesas. O grupo aceita somente o tipo Fixos de Casa.</p><CardArtworkPicker artworks={config.card_artworks} card={{ name: form.name, color: form.color, artwork_key: form.artwork_key, image_url: form.image_url }} onPending={setPendingCrop} onChange={art => setForm(f => ({ ...f, artwork_key: art?.key || null, color: art?.color || f.color, name: art?.key === 'household' ? 'Fixos de Casa' : f.name || art?.name || '', household: art?.key === 'household' || !!f.restricted_type_id, image_url: null, remove_image: true }))} onImage={(file, url) => { setCardFile(file); setForm(f => ({ ...f, image_url: url, remove_image: !file, ...(file ? { artwork_key: null } : {}) })); }} />{!form.artwork_key && !form.image_url && <label>Cor do modelo personalizado<input type="color" value={form.color} onChange={e => change('color', e.target.value)} /></label>}</>}<label className="cg-checkbox"><input type="checkbox" checked={form.active} onChange={e => change('active', e.target.checked)} /> Cadastro ativo</label><p className="cg-muted">Alterar o cadastro não muda os vencimentos de dívidas anteriores. Inativar preserva o histórico.</p></>}
    {dialog.kind === 'operation' && <><div className="cg-payment-modes" aria-label="Como deseja baixar o saldo?"><button type="button" aria-pressed={paymentMode === 'both'} onClick={() => choosePayment('both')}><Check /><strong>Quitar parcela inteira</strong><small>Baixar todo o saldo selecionado</small></button>{dialog.items.length === 1 && <button type="button" aria-pressed={paymentMode === 'partial'} onClick={() => choosePayment('partial')}><CircleDollarSign /><strong>Pagar valor parcial</strong><small>Escolher quanto será baixado</small></button>}{sharedPayment && <>{[1, 2].map(id => <button type="button" key={id} disabled={dialog.items.every(i => (id === 1 ? i.remaining_one_cents : i.remaining_two_cents) === 0)} aria-pressed={paymentMode === (id === 1 ? 'one' : 'two')} onClick={() => choosePayment(id === 1 ? 'one' : 'two')}><PersonPortrait kind={id === 1 ? 'man' : 'woman'} /><strong>Quitar parte de {name(id)}</strong><small>Preservar a parte da outra pessoa</small></button>)}</>}</div><div className="cg-payment-preview"><span>{dialog.items.length} {dialog.items.length === 1 ? 'parcela selecionada' : 'parcelas selecionadas'}</span><strong>{money(form.partial ? paymentPreview.amount : remaining)}</strong><small>{form.kind === 'discount' ? 'Valor que será abatido como desconto' : 'Valor que será registrado como pagamento'}</small></div><div className="cg-two-columns"><label>Tipo de lançamento<select value={form.kind} onChange={e => change('kind', e.target.value)}><option value="payment">Pagamento</option><option value="advance">Antecipação</option><option value="discount">Abatimento / desconto</option></select></label>{form.partial && <label>Qual parte será abatida?<select value={form.target} onChange={e => change('target', e.target.value)}><option value="both">Saldo total (proporcional)</option><option value="one">Somente {name(1)}</option><option value="two">Somente {name(2)}</option></select></label>}{form.kind !== 'discount' && <label>Quem efetivamente pagou?<select required value={form.paid_by} onChange={e => change('paid_by', e.target.value)}><option value="">Selecione</option><option value="1">{name(1)}</option><option value="2">{name(2)}</option></select><small>Quem fez o pagamento pode ser diferente de quem teve a parte quitada.</small></label>}<label>Data do lançamento<input required type="date" max={today()} value={form.occurred_on} onChange={e => change('occurred_on', e.target.value)} /></label>{form.partial && amountField('Valor a registrar (R$)')}</div><div className="cg-payment-split" aria-label="Saldo após este lançamento">{[1, 2].map(id => <article key={id}><span>{name(id)} · ficará pendente</span><strong>{money(id === 1 ? paymentPreview.one : paymentPreview.two)}</strong><small>{(id === 1 ? paymentPreview.one : paymentPreview.two) === 0 ? 'Parte quitada após confirmar' : 'Esta parte ainda precisa ser paga'}</small></article>)}</div><label>Observação opcional<textarea rows={2} maxLength={500} value={form.notes} onChange={e => change('notes', e.target.value)} /></label><p className="cg-muted">Confira os saldos acima antes de confirmar. Abatimento/desconto reduz a dívida sem registrar dinheiro pago. Em lote, a opção escolhida vale para todas as parcelas.</p></>}
    {dialog.kind === 'installment' && <><p className="cg-muted">Esta mudança afeta somente a parcela {dialog.item.number}, sem alterar a divisão padrão.</p>{amountField('Valor da parcela (R$)')}<label>Vencimento<input required type="date" value={form.due_on} onChange={e => change('due_on', e.target.value)} /></label>{dialog.responsibility === 'shared' && <ExpenseSplitFields amount={centsFromMoneyInput(form.value)} mode={form.split_mode} percent={Number(form.percent_one)} one={form.share_one_value || ''} names={[name(1), name(2)]} onChange={data => setForm(f => ({ ...f, ...data }))} />}</>}
    {dialog.kind === 'reason' && <><p>{dialog.action === 'reverse' ? 'O saldo correspondente será reaberto. O lançamento continuará no histórico, identificado como desfeito.' : 'A dívida sairá das áreas ativas e da projeção. Pagamentos e parcelas permanecerão no histórico de canceladas.'}</p><label>Motivo<textarea required minLength={5} maxLength={500} rows={3} value={form.reason} onChange={e => change('reason', e.target.value)} /></label></>}
    {dialog.kind === 'end' && <><p>A despesa não será gerada após o último mês indicado. Os meses anteriores e seus pagamentos serão preservados.</p><label>Último mês da cobrança<input required type="month" value={form.end_month} onChange={e => change('end_month', e.target.value)} /></label></>}
    </fieldset></div><footer className="cg-dialog-footer"><button type="button" disabled={busy} onClick={onClose}>Cancelar</button><button className="cg-primary" disabled={busy || pendingCrop || (dialog.kind === 'operation' && remaining <= 0) || (dialog.kind === 'debt' && !dialog.debt && (!config.institutions.some(i => i.active) || !config.types.some(i => i.active)))}>{busy ? 'Salvando…' : confirming ? (dialog.kind === 'reason' && dialog.action === 'cancel' ? 'Confirmar exclusão' : 'Confirmar alteração') : dialog.kind === 'operation' ? 'Confirmar lançamento' : 'Salvar'}</button></footer></form></OrderPopup>;
}


type InstitutionPlan = { balance_cents: number; remaining_cents: number; preview_hash: string; allocations: { id: number; name: string; number: number; shared: boolean; amount_cents: number; remaining_cents: number }[] };
function InstitutionPayment({ bank, month, config, initialTarget, busy, saveError, onClose, onSave }: { bank: number; month: string; config: Configuration; initialTarget: string; busy: boolean; saveError: string; onClose: () => void; onSave: (data: unknown) => Promise<boolean> }) {
  const [target, setTarget] = useState(initialTarget), [value, setValue] = useState(''), [mode, setMode] = useState('partial'), [occurred, setOccurred] = useState(today()), [notes, setNotes] = useState('');
  const [balance, setBalance] = useState<number>(), [plan, setPlan] = useState<InstitutionPlan>(), [error, setError] = useState(''), [loading, setLoading] = useState(false);
  const key = useRef(expenseRequestId());
  useEffect(() => {
    const controller = new AbortController(); setBalance(undefined); setPlan(undefined); setError('');
    void api<InstitutionPlan>('/institution-payments', 'POST', { institution_id: bank, month, target, amount_cents: 0, preview: true }, controller.signal).then(result => { if (!controller.signal.aborted) setBalance(result.balance_cents); }).catch((e: any) => { if (!controller.signal.aborted) setError(e.message); });
    return () => controller.abort();
  }, [bank, month, target]);
  const personName = config.people.find(p => p.id === (target === 'one' ? 1 : 2))?.name || 'Responsável';
  const amount = mode === 'total' ? balance || 0 : centsFromMoneyInput(value);
  const payload = { institution_id: bank, month, target, amount_cents: amount };
  const simulate = async () => { setLoading(true); setError(''); setPlan(undefined); try { setPlan(await api<InstitutionPlan>('/institution-payments', 'POST', { ...payload, preview: true })); } catch (e: any) { setError(e.message); } finally { setLoading(false); } };
  return <OrderPopup theme="expense" title="Pagar fatura do mês" eyebrow="CONTROLE DE GASTO" description={(config.institutions.find(i => i.id === bank)?.name || '') + ' · ' + monthLabel(month)} icon={CircleDollarSign} variant="budget" onClose={onClose} closeLabel="Fechar pagamento da fatura"><form className="cg-dialog cg-form cg-month-payment" onSubmit={e => { e.preventDefault(); if (plan) void onSave({ ...payload, request_key: key.current, preview_hash: plan.preview_hash, kind: 'payment', paid_by: target === 'one' ? 1 : 2, occurred_on: occurred, notes }); else void simulate(); }}><div className="cg-dialog-body">
    {(error || saveError) && <p role="alert">{error || saveError}</p>}
    <label>Qual parte será paga?<select value={target} disabled={busy || loading} onChange={e => { setTarget(e.target.value); setPlan(undefined); }}><option value="one">{config.people[0]?.name}</option><option value="two">{config.people[1]?.name}</option></select></label>
    <div className="cg-payment-preview"><span>Total pendente de {personName} neste mês</span><strong>{balance === undefined ? 'Carregando…' : money(balance)}</strong><small>Compras individuais + sua parte das compras do casal.</small></div>
    <div className="cg-payment-modes"><button type="button" aria-pressed={mode === 'total'} onClick={() => { setMode('total'); setPlan(undefined); }}><Check /><strong>Quitar minha parte</strong><small>Todo o saldo deste mês</small></button><button type="button" aria-pressed={mode === 'partial'} onClick={() => { setMode('partial'); setPlan(undefined); }}><CircleDollarSign /><strong>Pagar parte da fatura</strong><small>Informar um valor</small></button></div>
    <div className="cg-two-columns"><label>Valor do pagamento (R$)<input required inputMode="decimal" value={mode === 'total' ? moneyInputFromCents(balance || 0) : value} disabled={mode === 'total' || busy || loading} onChange={e => { setValue(maskMoneyInput(e.target.value)); setPlan(undefined); }} /></label><label>Data do pagamento<input required type="date" max={today()} value={occurred} onChange={e => setOccurred(e.target.value)} /></label></div>
    <p className="cg-muted">Somente {monthLabel(month)}: primeiro as compras pessoais, depois sua parte do casal. A outra pessoa e os próximos meses permanecem intactos.</p>
    {plan && <section className="cg-panel"><div className="cg-payment-split"><article><span>Saldo antes</span><strong>{money(plan.balance_cents)}</strong></article><article><span>Ficará pendente para {personName}</span><strong>{money(plan.remaining_cents)}</strong></article></div><h3>Confira a distribuição</h3><div className="cg-institution-allocation">{plan.allocations.map(i => <article key={i.id}><div><b>{i.name}</b><small>Parcela {i.number} · {i.shared ? 'Sua parte do casal' : 'Compra pessoal'}</small></div><strong>{money(i.amount_cents)}</strong><small>Restará nesta parte: {money(i.remaining_cents)}</small></article>)}</div></section>}
    <label>Observação opcional<textarea rows={2} maxLength={500} value={notes} onChange={e => setNotes(e.target.value)} /></label></div><footer className="cg-dialog-footer"><button type="button" disabled={busy || loading} onClick={onClose}>Cancelar</button>{plan && <button type="button" disabled={busy} onClick={() => setPlan(undefined)}>Editar valor</button>}<button className="cg-primary" disabled={busy || loading || balance === undefined || amount <= 0}>{busy ? 'Salvando…' : loading ? 'Simulando…' : plan ? 'Confirmar pagamento da fatura' : 'Simular distribuição'}</button></footer></form></OrderPopup>;
}

type PurchasePlan = { name: string; responsibility: string; total_cents: number; one_cents: number; two_cents: number; items: Installment[]; preview_hash: string };
function PurchaseSettlement({ bank, busy, saveError, onClose, onSave }: { bank: number; busy: boolean; saveError: string; onClose: () => void; onSave: (id: number, data: unknown) => Promise<boolean> }) {
  const [purchases, setPurchases] = useState<Debt[]>([]), [search, setSearch] = useState(''), [page, setPage] = useState(1), [last, setLast] = useState(1), [selectedDebt, setSelectedDebt] = useState<number>(), [plan, setPlan] = useState<PurchasePlan>(), [loading, setLoading] = useState(false), [error, setError] = useState(''), [occurred, setOccurred] = useState(today());
  const key = useRef(expenseRequestId());
  useEffect(() => { const controller = new AbortController(); setLoading(true); void api<Pager<Debt>>('/debts?institution=' + bank + '&status=active&sort=newest&page=' + page + '&q=' + encodeURIComponent(search), 'GET', undefined, controller.signal).then(r => { if (!controller.signal.aborted) { setPurchases(r.data.filter(d => d.recurrence !== 'monthly')); setLast(r.last_page); } }).catch((e: any) => { if (!controller.signal.aborted) setError(e.message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); }); return () => controller.abort(); }, [bank, page, search]);
  const choose = async (id: number) => { setLoading(true); setError(''); setPlan(undefined); try { setPlan(await api<PurchasePlan>('/debts/' + id + '/settlement', 'POST', { preview: true })); setSelectedDebt(id); key.current = expenseRequestId(); } catch (e: any) { setError(e.message); } finally { setLoading(false); } };
  return <OrderPopup theme="expense" title="Quitar compra" eyebrow="TODAS AS PARCELAS PENDENTES" description="Escolha uma compra para quitar o saldo inteiro, incluindo os próximos meses e as duas partes do casal." icon={Check} variant="budget" onClose={onClose} closeLabel="Fechar quitação da compra"><form className="cg-dialog cg-form" onSubmit={e => { e.preventDefault(); if (plan && selectedDebt) void onSave(selectedDebt, { request_key: key.current, preview_hash: plan.preview_hash, occurred_on: occurred }); }}><div className="cg-dialog-body">{(error || saveError) && <p role="alert">{error || saveError}</p>}
    {!plan ? <><label>Pesquisar compra<input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} /></label><div className="cg-institution-allocation">{purchases.map(d => <button type="button" className="cg-purchase-choice" disabled={loading} key={d.id} onClick={() => void choose(d.id)}><span><b>{d.name}</b><small>{d.installment_count} parcelas · {d.responsibility === 'shared' ? 'Casal' : 'Individual'}</small></span><strong>{money(d.remaining_cents)}</strong></button>)}{!loading && !purchases.length && <p>Nenhuma compra parcelada ou de pagamento único encontrada.</p>}</div><Pagination current={page} last={last} onChange={setPage} /></> : <><div className="cg-payment-preview"><span>{plan.name} · {plan.items.length} parcelas pendentes selecionadas</span><strong>{money(plan.total_cents)}</strong><small>{plan.responsibility === 'shared' ? 'Quitação integral das duas partes do casal.' : 'Quitação integral desta compra.'}</small></div><div className="cg-institution-allocation">{plan.items.map(i => <article key={i.id}><div><b>Parcela {i.number}</b><small>Vencimento {date(i.due_on)}</small></div><strong>{money(i.remaining_cents)}</strong></article>)}</div><label>Data da quitação<input required type="date" max={today()} value={occurred} onChange={e => setOccurred(e.target.value)} /></label><p className="cg-muted">Confirme somente depois de conferir as parcelas. A compra sairá de Gastos e permanecerá em Quitadas, com o histórico preservado.</p></>}
    </div><footer className="cg-dialog-footer"><button type="button" disabled={busy || loading} onClick={onClose}>Cancelar</button>{plan && <button type="button" disabled={busy} onClick={() => { setPlan(undefined); setSelectedDebt(undefined); }}>Escolher outra compra</button>}{plan && <button className="cg-primary" disabled={busy || loading || plan.total_cents <= 0}>{busy ? 'Salvando…' : 'Confirmar quitação da compra'}</button>}</footer></form></OrderPopup>;
}



function ExpenseMonthPicker({ month, onChange }: { month: string; onChange: (month: string) => void }) {
  const [open, setOpen] = useState(false), [year, setYear] = useState(Number(month.slice(0, 4)));
  const root = useRef<HTMLDivElement>(null), trigger = useRef<HTMLButtonElement>(null), yearInput = useRef<HTMLSelectElement>(null);
  const id = useId();
  const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
  const close = () => { setOpen(false); trigger.current?.focus(); };
  useEffect(() => {
    if (!open) return;
    yearInput.current?.focus();
    const outside = (event: PointerEvent) => { if (!root.current?.contains(event.target as Node)) setOpen(false); };
    document.addEventListener('pointerdown', outside);
    return () => document.removeEventListener('pointerdown', outside);
  }, [open]);
  const choose = (value: string) => { onChange(value); close(); };
  const move = (direction: number) => { const d = new Date(month + '-01T12:00:00'); d.setMonth(d.getMonth() + direction); const value = d.toLocaleDateString('sv-SE').slice(0, 7); if (value >= '2000-01' && value <= '2099-12') { onChange(value); setYear(Number(value.slice(0, 4))); } };
  return <div ref={root} className="cg-month cg-month-compact" onKeyDown={e => { if (e.key === 'Escape' && open) { e.preventDefault(); close(); } }} onBlur={e => { if (e.relatedTarget && !e.currentTarget.contains(e.relatedTarget as Node)) setOpen(false); }}>
    <button aria-label="Mês anterior do controle" disabled={month === '2000-01'} onClick={() => move(-1)}><ChevronLeft /></button>
    <button ref={trigger} className="cg-month-trigger" data-month={month} aria-label="Selecionar mês do Controle de Gasto" aria-haspopup="dialog" aria-expanded={open} aria-controls={id} onClick={() => { setYear(Number(month.slice(0, 4))); setOpen(value => !value); }}><CalendarDays /><strong>{month.slice(5, 7)}/{month.slice(0, 4)}</strong></button>
    <button aria-label="Próximo mês do controle" disabled={month === '2099-12'} onClick={() => move(1)}><ChevronRight /></button>
    {open && <div id={id} className="cg-month-popover" role="dialog" aria-label="Selecionar mês e ano"><header><button aria-label="Ano anterior" disabled={year === 2000} onClick={() => setYear(value => value - 1)}><ChevronLeft /></button><select ref={yearInput} aria-label="Ano do controle" value={year} onChange={e => setYear(Number(e.target.value))}>{Array.from({ length: 100 }, (_, i) => <option key={i} value={2000 + i}>{2000 + i}</option>)}</select><button aria-label="Próximo ano" disabled={year === 2099} onClick={() => setYear(value => value + 1)}><ChevronRight /></button></header><div className="cg-month-options">{months.map((label, i) => { const value = year + '-' + String(i + 1).padStart(2, '0'); return <button key={label} aria-label={label + ' de ' + year} aria-pressed={month === value} onClick={() => choose(value)}>{label.slice(0, 3)}</button>; })}</div><footer><button onClick={() => choose(currentMonth())}>Mês atual</button><button onClick={close}>Fechar</button></footer></div>}
  </div>;
}


type PaidPurchase = { id: number; name: string; institution_id: number; institution_name: string; type_id: number; type_name: string; installment_count: number; paid_cents: number; discount_cents: number };
function PaymentInstitutions({ month: initialMonth, config, name, mobile, onReverse }: { month: string; config: Configuration; name: (id: number) => string; mobile: boolean; onReverse: (id: number) => void }) {
  const [month, setMonth] = useState(initialMonth);
  const [selectedBank, setSelectedBank] = useState<number>();
  const [purchases, setPurchases] = useState<PaidPurchase[]>([]);
  const [selectedType, setSelectedType] = useState<string>('');
  const [selectedPurchase, setSelectedPurchase] = useState<number>();
  const [entries, setEntries] = useState<Pager<Entry>>();
  const [page, setPage] = useState(1);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    const controller = new AbortController();
    void api<PaidPurchase[]>('/advances?grouped=1&month=' + month, 'GET', undefined, controller.signal).then(setPurchases).catch(e => { if (!controller.signal.aborted) setError(e.message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [month]);
  useEffect(() => {
    if (!selectedPurchase) return;
    const controller = new AbortController(); setEntries(undefined);
    void api<Pager<Entry>>('/advances?month=' + month + '&debt=' + selectedPurchase + '&page=' + page, 'GET', undefined, controller.signal).then(setEntries).catch(e => { if (!controller.signal.aborted) setError(e.message); });
    return () => controller.abort();
  }, [selectedPurchase, month, page]);
  const banks = [...config.institutions, ...purchases.filter(p => !config.institutions.some(b => b.id === Number(p.institution_id))).map(p => ({ id: Number(p.institution_id), name: p.institution_name, active: false, due_day: 1, color: '#557799', restricted_type_id: null }))].filter((bank, index, all) => all.findIndex(b => b.id === bank.id) === index);
  const historyTypes = [...config.types, ...purchases.filter(p => !config.types.some(t => t.id === Number(p.type_id))).map(p => ({ id: Number(p.type_id), name: p.type_name, active: false }))].filter((t, index, all) => all.findIndex(other => other.id === t.id) === index);
  const visibleBanks = selectedBank ? banks.filter(b => b.id === selectedBank) : banks;
  return <section className="cg-payment-institutions"><div className="cg-section-heading"><div><span className="cg-eyebrow">PAGAMENTOS DO MÊS</span><h2>Pagamentos por instituição</h2><p>Abra uma instituição e escolha o mês para consultar os pagamentos.</p></div></div>{error && <p role="alert">{error}</p>}{loading && <p role="status">Carregando pagamentos…</p>}{selectedBank && <div className="cg-payment-month"><button onClick={() => { setSelectedBank(undefined); setMonth(initialMonth); setSelectedType(''); setSelectedPurchase(undefined); }}> <ArrowLeft /> Voltar às instituições</button><ExpenseMonthPicker month={month} onChange={value => { setMonth(value); setSelectedType(''); setSelectedPurchase(undefined); setPage(1); }} /></div>}{visibleBanks.map(bank => <article className={"cg-panel cg-payment-bank" + (mobile ? ' cg-payment-bank-mobile' : '')} key={bank.id}><button className="cg-payment-bank-heading" aria-label={"Ver pagamentos de " + bank.name} aria-expanded={selectedBank === bank.id} onClick={() => { setSelectedBank(selectedBank === bank.id ? undefined : bank.id); setSelectedType(''); setSelectedPurchase(undefined); }}><div className="cg-payment-art"><CardArtworkView card={bank} artworks={config.card_artworks} /></div><div><b>{bank.name}</b><small>Total pago no mês</small><strong>{money(purchases.filter(p => Number(p.institution_id) === bank.id).reduce((s, p) => s + Number(p.paid_cents), 0))}</strong></div><ChevronRight /></button>{selectedBank === bank.id && <div className="cg-payment-types">{historyTypes.filter(t => purchases.some(p => Number(p.institution_id) === bank.id && Number(p.type_id) === t.id)).map(type => {
    const items = purchases.filter(p => Number(p.institution_id) === bank.id && Number(p.type_id) === type.id);
    const key = bank.id + '-' + type.id;
    return <div key={type.id}><button aria-expanded={selectedType === key} onClick={() => { setSelectedType(selectedType === key ? '' : key); setSelectedPurchase(undefined); setPage(1); }}><b>{type.name}</b><small>{items.length} {items.length === 1 ? 'compra' : 'compras'} · {items.reduce((s, p) => s + Number(p.installment_count), 0)} parcelas</small><strong>{money(items.reduce((s, p) => s + Number(p.paid_cents), 0))}</strong></button>{selectedType === key && <div className="cg-paid-purchases">{items.map(p => <div key={p.id}><button className="cg-paid-purchase" aria-expanded={selectedPurchase === p.id} onClick={() => { setSelectedPurchase(selectedPurchase === p.id ? undefined : p.id); setPage(1); }}><span><b>{p.name}</b><small>{p.installment_count} parcelas{Number(p.discount_cents) > 0 && ' · abatimento ' + money(p.discount_cents)}</small></span><strong>{money(p.paid_cents)}</strong><ChevronRight /></button>{selectedPurchase === p.id && <div className="cg-payments-panel">{!entries ? <p role="status">Carregando lançamentos…</p> : <>{entries.data.map(e => <EntryRow key={e.id} entry={e} name={name} onReverse={() => onReverse(e.id)} />)}<Pagination current={entries.current_page} last={entries.last_page} onChange={setPage} /></>}</div>}</div>)}{!items.length && <p className="cg-muted">Nenhum pagamento deste tipo no mês.</p>}</div>}</div>;
  })}</div>}</article>)}{!loading && !visibleBanks.length && <Empty title="Nenhum lançamento neste mês" text="Os pagamentos aparecerão agrupados por instituição." />}</section>;
}
